/**
 * Reduction in worst-case frame time between a baseline run and a
 * tuned run, as a fraction (0.3 = 30 % faster). The acceptance
 * criterion is `>= 0.3`.
 */
export function worstCaseReduction(baseline: RenderBenchReport, tuned: RenderBenchReport): number {
  const base = Math.max(baseline.p95Ms, baseline.worstMs);
  const tunedMs = Math.min(tuned.p95Ms, tuned.worstMs);
  if (base <= 0) return 0;
  return (base - tunedMs) / base;
}

